-- N5 · n5-my-town · My town
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n5-my-town', 'lang-ja', ll.id, 'n5-my-town', 'わたしの町', 'My town', false, 5
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-town-l0', 'rdg-ja-n5-my-town', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-my-town-l1', 'rdg-ja-n5-my-town', 1, 0, '今日は、わたしの町の話をします。', 'きょう わ、わたし の まち の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"わたし"},{"t":"の"},{"t":"町","r":"まち"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my town.'),
  ('rdg-ja-n5-my-town-l2', 'rdg-ja-n5-my-town', 2, 1, 'わたしの町は小さいです。', 'わたし の まち わ ちいさい です。', '[{"t":"わたし"},{"t":"の"},{"t":"町","r":"まち"},{"t":"は"},{"t":"小","r":"ちい"},{"t":"さい"},{"t":"です"},{"t":"。"}]'::jsonb, 'My town is small.'),
  ('rdg-ja-n5-my-town-l3', 'rdg-ja-n5-my-town', 3, 1, 'でも、とても静かです。', 'でも、とても しずか です。', '[{"t":"でも"},{"t":"、"},{"t":"とても"},{"t":"静","r":"しず"},{"t":"か"},{"t":"です"},{"t":"。"}]'::jsonb, 'But it is very quiet.'),
  ('rdg-ja-n5-my-town-l4', 'rdg-ja-n5-my-town', 4, 2, '駅の前に店があります。', 'えき の まえ に みせ が あります。', '[{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"に"},{"t":"店","r":"みせ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a shop in front of the station.'),
  ('rdg-ja-n5-my-town-l5', 'rdg-ja-n5-my-town', 5, 2, 'パンがおいしい店です。', 'パン が おいしい みせ です。', '[{"t":"パン"},{"t":"が"},{"t":"おいしい"},{"t":"店","r":"みせ"},{"t":"です"},{"t":"。"}]'::jsonb, 'It is a shop with delicious bread.'),
  ('rdg-ja-n5-my-town-l6', 'rdg-ja-n5-my-town', 6, 2, '毎朝、そこでパンを買います。', 'まいあさ、そこ で パン お かいます。', '[{"t":"毎朝","r":"まいあさ"},{"t":"、"},{"t":"そこ"},{"t":"で"},{"t":"パン"},{"t":"を"},{"t":"買","r":"か"},{"t":"います"},{"t":"。"}]'::jsonb, 'Every morning I buy bread there.'),
  ('rdg-ja-n5-my-town-l7', 'rdg-ja-n5-my-town', 7, 3, '大きい公園もあります。', 'おおきい こうえん も あります。', '[{"t":"大","r":"おお"},{"t":"きい"},{"t":"公園","r":"こうえん"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is also a big park.'),
  ('rdg-ja-n5-my-town-l8', 'rdg-ja-n5-my-town', 8, 3, '公園に木がたくさんあります。', 'こうえん に き が たくさん あります。', '[{"t":"公園","r":"こうえん"},{"t":"に"},{"t":"木","r":"き"},{"t":"が"},{"t":"たくさん"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There are many trees in the park.'),
  ('rdg-ja-n5-my-town-l9', 'rdg-ja-n5-my-town', 9, 4, 'かわも近くにあります。', 'かわ も ちかく に あります。', '[{"t":"かわ"},{"t":"も"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"に"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is also a river nearby.'),
  ('rdg-ja-n5-my-town-l10', 'rdg-ja-n5-my-town', 10, 4, '日曜日は、よくかわの近くをさんぽします。', 'にちようび わ、よく かわ の ちかく お さんぽ します。', '[{"t":"日曜日","r":"にちようび"},{"t":"は"},{"t":"、"},{"t":"よく"},{"t":"かわ"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"を"},{"t":"さんぽ"},{"t":"します"},{"t":"。"}]'::jsonb, 'On Sundays I often take a walk by the river.'),
  ('rdg-ja-n5-my-town-l11', 'rdg-ja-n5-my-town', 11, 5, '町の人はみんなやさしいです。', 'まち の ひと わ みんな やさしい です。', '[{"t":"町","r":"まち"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"みんな"},{"t":"やさしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Everyone in town is kind.'),
  ('rdg-ja-n5-my-town-l12', 'rdg-ja-n5-my-town', 12, 5, 'わたしは、この町が大好きです。', 'わたし わ、この まち が だいすき です。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"この"},{"t":"町","r":"まち"},{"t":"が"},{"t":"大好","r":"だいす"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I really love this town.'),
  ('rdg-ja-n5-my-town-l13', 'rdg-ja-n5-my-town', 13, 5, 'みなさんの町は、どうですか。', 'みなさん の まち わ、どう です か。', '[{"t":"みなさん"},{"t":"の"},{"t":"町","r":"まち"},{"t":"は"},{"t":"、"},{"t":"どう"},{"t":"です"},{"t":"か"},{"t":"。"}]'::jsonb, 'What is your town like, everyone?')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-my-town')
ON CONFLICT (reading_id, index) DO NOTHING;

