  ('rdg-ja-n5-favorite-food-l1', 'rdg-ja-n5-favorite-food', 1, 0, 'わたしの好きな食べ物は、ラーメンです。', 'わたし の すきな たべもの わ、ラーメン です。', '[{"t":"わたし"},{"t":"の"},{"t":"好","r":"す"},{"t":"き"},{"t":"な"},{"t":"食","r":"た"},{"t":"べ"},{"t":"物","r":"もの"},{"t":"は"},{"t":"、"},{"t":"ラーメン"},{"t":"です"},{"t":"。"}]'::jsonb, 'My favourite food is ramen.'),
  ('rdg-ja-n5-favorite-food-l2', 'rdg-ja-n5-favorite-food', 2, 1, 'あついラーメンが好きです。', 'あつい ラーメン が すき です。', '[{"t":"あつい"},{"t":"ラーメン"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like hot ramen.'),
  ('rdg-ja-n5-favorite-food-l3', 'rdg-ja-n5-favorite-food', 3, 1, '肉もたまごも入っています。', 'にく も たまご も はいって います。', '[{"t":"肉","r":"にく"},{"t":"も"},{"t":"たまご"},{"t":"も"},{"t":"入","r":"はい"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'It has meat and egg in it.'),
  ('rdg-ja-n5-favorite-food-l4', 'rdg-ja-n5-favorite-food', 4, 2, '駅の近くに、小さい店があります。', 'えき の ちかく に、ちいさい みせ が あります。', '[{"t":"駅","r":"えき"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"に"},{"t":"、"},{"t":"小","r":"ちい"},{"t":"さい"},{"t":"店","r":"みせ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a small shop near the station.'),
  ('rdg-ja-n5-favorite-food-l5', 'rdg-ja-n5-favorite-food', 5, 2, 'わたしは、いつもそこで食べます。', 'わたし わ、いつも そこ で たべます。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"いつも"},{"t":"そこ"},{"t":"で"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'I always eat there.'),
  ('rdg-ja-n5-favorite-food-l6', 'rdg-ja-n5-favorite-food', 6, 3, 'その店は安いです。', 'その みせ わ やすい です。', '[{"t":"その"},{"t":"店","r":"みせ"},{"t":"は"},{"t":"安","r":"やす"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'That shop is cheap.'),
  ('rdg-ja-n5-favorite-food-l7', 'rdg-ja-n5-favorite-food', 7, 3, 'そして、とてもおいしいです。', 'そして、とても おいしい です。', '[{"t":"そして"},{"t":"、"},{"t":"とても"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'And it is very delicious.'),
  ('rdg-ja-n5-favorite-food-l8', 'rdg-ja-n5-favorite-food', 8, 4, '週に二かい、友だちと行きます。', 'しゅう に にかい、ともだち と いきます。', '[{"t":"週","r":"しゅう"},{"t":"に"},{"t":"二","r":"に"},{"t":"かい"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'Twice a week, I go with a friend.'),
  ('rdg-ja-n5-favorite-food-l9', 'rdg-ja-n5-favorite-food', 9, 4, '二人でラーメンを食べて、たくさん話します。', 'ふたり で ラーメン お たべて、たくさん はなします。', '[{"t":"二人","r":"ふたり"},{"t":"で"},{"t":"ラーメン"},{"t":"を"},{"t":"食","r":"た"},{"t":"べて"},{"t":"、"},{"t":"たくさん"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'The two of us eat ramen and talk a lot.'),
  ('rdg-ja-n5-favorite-food-l10', 'rdg-ja-n5-favorite-food', 10, 5, '家でも作りますが、店のほうがおいしいです。', 'いえ でも つくります が、みせ の ほう が おいしい です。', '[{"t":"家","r":"いえ"},{"t":"でも"},{"t":"作","r":"つく"},{"t":"ります"},{"t":"が"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"の"},{"t":"ほうが"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I make it at home too, but the shop’s tastes better.'),
  ('rdg-ja-n5-favorite-food-l11', 'rdg-ja-n5-favorite-food', 11, 5, 'みなさんの好きな食べ物は、何ですか。', 'みなさん の すきな たべもの わ、なん です か。', '[{"t":"みなさん"},{"t":"の"},{"t":"好","r":"す"},{"t":"き"},{"t":"な"},{"t":"食","r":"た"},{"t":"べ"},{"t":"物","r":"もの"},{"t":"は"},{"t":"、"},{"t":"何","r":"なん"},{"t":"ですか"},{"t":"。"}]'::jsonb, 'What is your favourite food, everyone?')
