  ('rdg-ja-n5-best-friend-l3', 'rdg-ja-n5-best-friend', 3, 1, '二年前、学校で会いました。', 'にねん まえ、がっこう で あいました。', '[{"t":"二","r":"にねんまえ"},{"t":"年"},{"t":"前"},{"t":"、"},{"t":"学校","r":"がっこう"},{"t":"で"},{"t":"会","r":"あ"},{"t":"いました"},{"t":"。"}]'::jsonb, 'We met at school two years ago.'),
  ('rdg-ja-n5-best-friend-l4', 'rdg-ja-n5-best-friend', 4, 2, 'たなかさんは背が高いです。', 'たなか さん わ せ が たかい です。', '[{"t":"たなか"},{"t":"さん"},{"t":"は"},{"t":"背","r":"せ"},{"t":"が"},{"t":"高","r":"たか"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'Tanaka is tall.'),
  ('rdg-ja-n5-best-friend-l5', 'rdg-ja-n5-best-friend', 5, 2, '目が大きくて、よくわらいます。', 'め が おおきくて、よく わらいます。', '[{"t":"目","r":"め"},{"t":"が"},{"t":"大","r":"おお"},{"t":"きくて"},{"t":"、"},{"t":"よく"},{"t":"わらいます"},{"t":"。"}]'::jsonb, 'Tanaka has big eyes and laughs a lot.'),
  ('rdg-ja-n5-best-friend-l6', 'rdg-ja-n5-best-friend', 6, 3, 'たなかさんは、本を読むのが好きです。', 'たなか さん わ、ほん お よむ の が すき です。', '[{"t":"たなか"},{"t":"さん"},{"t":"は"},{"t":"、"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"む"},{"t":"の"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'Tanaka likes reading books.'),
  ('rdg-ja-n5-best-friend-l7', 'rdg-ja-n5-best-friend', 7, 3, '雨の日は、家で本を読みます。', 'あめ の ひ わ、いえ で ほん お よみます。', '[{"t":"雨","r":"あめ"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"は"},{"t":"、"},{"t":"家","r":"いえ"},{"t":"で"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"みます"},{"t":"。"}]'::jsonb, 'On rainy days Tanaka reads books at home.'),
  ('rdg-ja-n5-best-friend-l8', 'rdg-ja-n5-best-friend', 8, 4, '休みの日は、いっしょに出かけます。', 'やすみ の ひ わ、いっしょ に でかけます。', '[{"t":"休","r":"やす"},{"t":"み"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"は"},{"t":"、"},{"t":"いっしょ"},{"t":"に"},{"t":"出","r":"で"},{"t":"かけます"},{"t":"。"}]'::jsonb, 'On days off we go out together.'),
