INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-saturday-shopping-l0', 'rdg-ja-n5-saturday-shopping', 0, 0, '土曜日は、いつも買い物に行きます。', 'どようび わ、いつも かいもの に いきます。', '[{"t":"土曜日","r":"どようび"},{"t":"は"},{"t":"、"},{"t":"いつも"},{"t":"買","r":"か"},{"t":"い"},{"t":"物","r":"もの"},{"t":"に"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'On Saturdays I always go shopping.'),
  ('rdg-ja-n5-saturday-shopping-l1', 'rdg-ja-n5-saturday-shopping', 1, 1, '午前十時に家を出ます。', 'ごぜん じゅうじ に いえ お でます。', '[{"t":"午前","r":"ごぜんじゅうじ"},{"t":"十時"},{"t":"に"},{"t":"家","r":"いえ"},{"t":"を"},{"t":"出","r":"で"},{"t":"ます"},{"t":"。"}]'::jsonb, 'I leave the house at ten in the morning.'),
  ('rdg-ja-n5-saturday-shopping-l2', 'rdg-ja-n5-saturday-shopping', 2, 1, '電車で大きい店へ行きます。', 'でんしゃ で おおきい みせ え いきます。', '[{"t":"電車","r":"でんしゃ"},{"t":"で"},{"t":"大","r":"おお"},{"t":"きい"},{"t":"店","r":"みせ"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I go to a big store by train.'),
  ('rdg-ja-n5-saturday-shopping-l3', 'rdg-ja-n5-saturday-shopping', 3, 2, 'はじめに、くだものを買います。', 'はじめに、くだもの お かいます。', '[{"t":"はじめに"},{"t":"、"},{"t":"くだもの"},{"t":"を"},{"t":"買","r":"か"},{"t":"います"},{"t":"。"}]'::jsonb, 'First, I buy fruit.'),
  ('rdg-ja-n5-saturday-shopping-l4', 'rdg-ja-n5-saturday-shopping', 4, 2, 'りんごは少し高いです。', 'りんご わ すこし たかい です。', '[{"t":"りんご"},{"t":"は"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"高","r":"たか"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'Apples are a little expensive.'),
  ('rdg-ja-n5-saturday-shopping-l5', 'rdg-ja-n5-saturday-shopping', 5, 2, 'でも、バナナは安いです。', 'でも、バナナ わ やすい です。', '[{"t":"でも"},{"t":"、"},{"t":"バナナ"},{"t":"は"},{"t":"安","r":"やす"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'But bananas are cheap.'),
  ('rdg-ja-n5-saturday-shopping-l6', 'rdg-ja-n5-saturday-shopping', 6, 3, 'それから、新しいくつを見ます。', 'それから、あたらしい くつ お みます。', '[{"t":"それから"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"くつ"},{"t":"を"},{"t":"見","r":"み"},{"t":"ます"},{"t":"。"}]'::jsonb, 'Then I look at new shoes.'),
  ('rdg-ja-n5-saturday-shopping-l7', 'rdg-ja-n5-saturday-shopping', 7, 3, '白いくつが好きです。', 'しろい くつ が すき です。', '[{"t":"白","r":"しろ"},{"t":"い"},{"t":"くつ"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like white shoes.'),
  ('rdg-ja-n5-saturday-shopping-l8', 'rdg-ja-n5-saturday-shopping', 8, 4, '昼ごはんは、店で食べます。', 'ひるごはん わ、みせ で たべます。', '[{"t":"昼","r":"ひる"},{"t":"ごはん"},{"t":"は"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"で"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'I eat lunch at the store.'),
  ('rdg-ja-n5-saturday-shopping-l9', 'rdg-ja-n5-saturday-shopping', 9, 4, 'お茶を飲んで、少し休みます。', 'おちゃ お のんで、すこし やすみます。', '[{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"飲","r":"の"},{"t":"んで"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"休","r":"やす"},{"t":"みます"},{"t":"。"}]'::jsonb, 'I drink tea and rest a little.'),
  ('rdg-ja-n5-saturday-shopping-l10', 'rdg-ja-n5-saturday-shopping', 10, 5, '四時に家へ帰ります。', 'よじ に いえ え かえります。', '[{"t":"四時","r":"よじ"},{"t":"に"},{"t":"家","r":"いえ"},{"t":"へ"},{"t":"帰","r":"かえ"},{"t":"ります"},{"t":"。"}]'::jsonb, 'I go home at four.'),
  ('rdg-ja-n5-saturday-shopping-l11', 'rdg-ja-n5-saturday-shopping', 11, 5, '買い物は楽しいです。', 'かいもの わ たのしい です。', '[{"t":"買","r":"か"},{"t":"い"},{"t":"物","r":"もの"},{"t":"は"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Shopping is fun.')
