  ('rdg-ja-n5-japanese-class-l2', 'rdg-ja-n5-japanese-class', 2, 1, 'クラスは、月曜日と水曜日にあります。', 'クラス わ、げつようび と すいようび に あります。', '[{"t":"クラス"},{"t":"は"},{"t":"、"},{"t":"月曜日","r":"げつようび"},{"t":"と"},{"t":"水曜日","r":"すいようび"},{"t":"に"},{"t":"あります"},{"t":"。"}]'::jsonb, 'The class is on Mondays and Wednesdays.'),
  ('rdg-ja-n5-japanese-class-l3', 'rdg-ja-n5-japanese-class', 3, 1, '午後六時にはじまります。', 'ごご ろくじ に はじまります。', '[{"t":"午後","r":"ごごろくじ"},{"t":"六時"},{"t":"に"},{"t":"はじまります"},{"t":"。"}]'::jsonb, 'It starts at six in the afternoon.'),
  ('rdg-ja-n5-japanese-class-l4', 'rdg-ja-n5-japanese-class', 4, 2, '先生は、やさしい女の人です。', 'せんせい わ、やさしい おんな の ひと です。', '[{"t":"先生","r":"せんせい"},{"t":"は"},{"t":"、"},{"t":"やさしい"},{"t":"女","r":"おんな"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"です"},{"t":"。"}]'::jsonb, 'The teacher is a kind woman.'),
  ('rdg-ja-n5-japanese-class-l5', 'rdg-ja-n5-japanese-class', 5, 2, 'いつも、ゆっくり話してくれます。', 'いつも、ゆっくり はなして くれます。', '[{"t":"いつも"},{"t":"、"},{"t":"ゆっくり"},{"t":"話","r":"はな"},{"t":"して"},{"t":"くれます"},{"t":"。"}]'::jsonb, 'She always speaks slowly for us.'),
  ('rdg-ja-n5-japanese-class-l6', 'rdg-ja-n5-japanese-class', 6, 3, 'クラスに学生が八人います。', 'クラス に がくせい が はちにん います。', '[{"t":"クラス"},{"t":"に"},{"t":"学生","r":"がくせい"},{"t":"が"},{"t":"八人","r":"はちにん"},{"t":"います"},{"t":"。"}]'::jsonb, 'There are eight students in the class.'),
  ('rdg-ja-n5-japanese-class-l7', 'rdg-ja-n5-japanese-class', 7, 3, 'みんな、外国から来ました。', 'みんな、がいこく から きました。', '[{"t":"みんな"},{"t":"、"},{"t":"外国","r":"がいこく"},{"t":"から"},{"t":"来","r":"き"},{"t":"ました"},{"t":"。"}]'::jsonb, 'Everyone came from abroad.'),
  ('rdg-ja-n5-japanese-class-l8', 'rdg-ja-n5-japanese-class', 8, 4, 'ひらがなとカタカナを書きます。', 'ひらがな と カタカナ お かきます。', '[{"t":"ひらがな"},{"t":"と"},{"t":"カタカナ"},{"t":"を"},{"t":"書","r":"か"},{"t":"きます"},{"t":"。"}]'::jsonb, 'We write hiragana and katakana.'),
  ('rdg-ja-n5-japanese-class-l9', 'rdg-ja-n5-japanese-class', 9, 4, '漢字は、まだ少ししかわかりません。', 'かんじ わ、まだ すこし しか わかりません。', '[{"t":"漢字","r":"かんじ"},{"t":"は"},{"t":"、"},{"t":"まだ"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"しか"},{"t":"わかりません"},{"t":"。"}]'::jsonb, 'I still only know a few kanji.'),
  ('rdg-ja-n5-japanese-class-l10', 'rdg-ja-n5-japanese-class', 10, 5, 'クラスの友だちと日本語で話します。', 'クラス の ともだち と にほんご で はなします。', '[{"t":"クラス"},{"t":"の"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"日本語","r":"にほんご"},{"t":"で"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'I talk with my classmates in Japanese.'),
  ('rdg-ja-n5-japanese-class-l11', 'rdg-ja-n5-japanese-class', 11, 5, 'まちがえても、だいじょうぶです。', 'まちがえて も、だいじょうぶ です。', '[{"t":"まちがえて"},{"t":"も"},{"t":"、"},{"t":"だいじょうぶ"},{"t":"です"},{"t":"。"}]'::jsonb, 'It’s okay to make mistakes.'),
  ('rdg-ja-n5-japanese-class-l12', 'rdg-ja-n5-japanese-class', 12, 6, '日本語のクラスは楽しいです。', 'にほんご の クラス わ たのしい です。', '[{"t":"日本語","r":"にほんご"},{"t":"の"},{"t":"クラス"},{"t":"は"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'My Japanese class is fun.'),
