SELECT v.* FROM (VALUES
  ('rdg-ja-n5-weather-seasons-l0', 'rdg-ja-n5-weather-seasons', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-weather-seasons-l1', 'rdg-ja-n5-weather-seasons', 1, 0, '今日は、天気の話をします。', 'きょう わ、てんき の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"天気","r":"てんき"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about the weather.'),
