  ('rdg-ja-n5-my-pet-l3', 'rdg-ja-n5-my-pet', 3, 1, '名前は「モモ」です。', 'なまえ わ「モモ」です。', '[{"t":"名前","r":"なまえ"},{"t":"は"},{"t":"「"},{"t":"モモ"},{"t":"」"},{"t":"です"},{"t":"。"}]'::jsonb, 'Its name is Momo.'),
  ('rdg-ja-n5-my-pet-l4', 'rdg-ja-n5-my-pet', 4, 2, 'モモは三さいです。', 'モモ わ さんさい です。', '[{"t":"モモ"},{"t":"は"},{"t":"三","r":"さん"},{"t":"さい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Momo is three years old.'),
  ('rdg-ja-n5-my-pet-l5', 'rdg-ja-n5-my-pet', 5, 2, 'けは茶色で、目は黒いです。', 'け わ ちゃいろ で、め わ くろい です。', '[{"t":"け"},{"t":"は"},{"t":"茶色","r":"ちゃいろ"},{"t":"で"},{"t":"、"},{"t":"目","r":"め"},{"t":"は"},{"t":"黒","r":"くろ"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'Its fur is brown and its eyes are black.'),
  ('rdg-ja-n5-my-pet-l6', 'rdg-ja-n5-my-pet', 6, 3, '朝と夕方に、いっしょにさんぽします。', 'あさ と ゆうがた に、いっしょ に さんぽ します。', '[{"t":"朝","r":"あさ"},{"t":"と"},{"t":"夕方","r":"ゆうがた"},{"t":"に"},{"t":"、"},{"t":"いっしょ"},{"t":"に"},{"t":"さんぽ"},{"t":"します"},{"t":"。"}]'::jsonb, 'Morning and evening, we go for a walk together.'),
