  ('rdg-ja-n5-birthday-party-l4', 'rdg-ja-n5-birthday-party', 4, 2, 'みんなで歌を歌いました。', 'みんな で うた お うたいました。', '[{"t":"みんな"},{"t":"で"},{"t":"歌","r":"うた"},{"t":"を"},{"t":"歌","r":"うた"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Everyone sang a song together.'),
  ('rdg-ja-n5-birthday-party-l5', 'rdg-ja-n5-birthday-party', 5, 3, 'わたしは、友だちに新しい本をあげました。', 'わたし わ、ともだち に あたらしい ほん お あげました。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"に"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"あげました"},{"t":"。"}]'::jsonb, 'I gave my friend a new book.'),
  ('rdg-ja-n5-birthday-party-l6', 'rdg-ja-n5-birthday-party', 6, 3, '友だちは、とてもよろこびました。', 'ともだち わ、とても よろこびました。', '[{"t":"友","r":"とも"},{"t":"だち"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"よろこびました"},{"t":"。"}]'::jsonb, 'My friend was very pleased.'),
  ('rdg-ja-n5-birthday-party-l7', 'rdg-ja-n5-birthday-party', 7, 4, 'ケーキは、とてもおいしかったです。', 'ケーキ わ、とても おいしかった です。', '[{"t":"ケーキ"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"おいしかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The cake was very delicious.'),
  ('rdg-ja-n5-birthday-party-l8', 'rdg-ja-n5-birthday-party', 8, 4, 'みんなで、たくさん話してわらいました。', 'みんな で、たくさん はなして わらいました。', '[{"t":"みんな"},{"t":"で"},{"t":"、"},{"t":"たくさん"},{"t":"話","r":"はな"},{"t":"して"},{"t":"わらいました"},{"t":"。"}]'::jsonb, 'We all talked a lot and laughed.'),
  ('rdg-ja-n5-birthday-party-l9', 'rdg-ja-n5-birthday-party', 9, 5, '十一時に、みんな家へ帰りました。', 'じゅういちじ に、みんな いえ え かえりました。', '[{"t":"十一時","r":"じゅういちじ"},{"t":"に"},{"t":"、"},{"t":"みんな"},{"t":"家","r":"いえ"},{"t":"へ"},{"t":"帰","r":"かえ"},{"t":"りました"},{"t":"。"}]'::jsonb, 'At eleven, everyone went home.'),
